def backfill_opening_batches(apps, schema_editor):
    """
    Seed one opening FIFO layer per product with positive on-hand stock so
    subsequent sales can consume cost layers. Historical purchase invoices are
    not reconstructed (would double-count against current_stock_quantity).
    """
    Product = apps.get_model("inventory", "Product")
    ProductBatch = apps.get_model("inventory", "ProductBatch")
    now = timezone.now()
    batch: list = []
    for p in Product.objects.filter(current_stock_quantity__gt=0).iterator(chunk_size=500):
        qty = int(p.current_stock_quantity or 0)
        if qty <= 0:
            continue
        batch.append(
            ProductBatch(
                product_id=p.pk,
                purchase_line=None,
                quantity=qty,
                remaining_quantity=qty,
                cost_price=p.buy_price,
                received_at=getattr(p, "created_at", None) or now,
            ),
        )
        if len(batch) >= 500:
            ProductBatch.objects.bulk_create(batch, batch_size=500)
            batch.clear()
    if batch:
        ProductBatch.objects.bulk_create(batch, batch_size=500)


def noop_reverse(apps, schema_editor):
    ProductBatch = apps.get_model("inventory", "ProductBatch")
    ProductBatch.objects.filter(purchase_line__isnull=True).delete()


